package com.crm.customer;
import com.crm.customer.service.*;import com.crm.customer.repository.*;import com.crm.customer.entity.*;import org.junit.jupiter.api.*;import org.springframework.data.domain.*;import java.util.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;
class ClientCasePolicyTest {CustomerPersonalService personal;CustomerRepository customers;ClientCaseRepository cases;ClientCaseMessageRepository messages;ClientCaseEventRepository events;ClientCaseService service;ClientCase row;Customer contact;
 @BeforeEach void setup(){AssignedContactPolicyTest.role("CLIENT");personal=mock(CustomerPersonalService.class);customers=mock(CustomerRepository.class);cases=mock(ClientCaseRepository.class);messages=mock(ClientCaseMessageRepository.class);events=mock(ClientCaseEventRepository.class);service=new ClientCaseService(personal,customers,cases,messages,events);when(personal.own(any())).thenReturn(new CustomerPersonalService.Profile("7","Client",null,null,null));contact=new Customer();contact.setId(7L);when(customers.lockById(7L)).thenReturn(Optional.of(contact));row=new ClientCase();row.setId(9L);row.setCustomerId(7L);row.setSubject("Request");row.setDescription("Description");row.setRequestId(UUID.randomUUID().toString());when(cases.findById(9L)).thenReturn(Optional.of(row));when(cases.lock(9L)).thenReturn(Optional.of(row));when(cases.saveAndFlush(any())).thenAnswer(c->{ClientCase r=c.getArgument(0);r.setId(10L);return r;});when(messages.saveAndFlush(any())).thenAnswer(c->{ClientCaseMessage r=c.getArgument(0);r.setId(11L);return r;});}@AfterEach void clear(){org.springframework.security.core.context.SecurityContextHolder.clearContext();}
 @Test void createResolvesCustomerAndStoresOpeningHistory(){var r=service.create(new ClientCaseService.NewCase(UUID.randomUUID().toString(),"Subject","Body"));assertNull(r.customerId());verify(cases).saveAndFlush(argThat(c->c.getCustomerId().equals(7L)));verify(events).saveAndFlush(argThat(e->e.getCaseId().equals(10L)&&e.getStatus().equals("OPEN")&&e.getAuthorId().equals(42L)));}
 @Test void newCaseRetryDoesNotDuplicateAndDifferentContentConflicts(){when(cases.findByRequestId(row.getRequestId())).thenReturn(Optional.of(row));service.create(new ClientCaseService.NewCase(row.getRequestId(),"Request","Description"));verify(cases,never()).saveAndFlush(any());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.create(new ClientCaseService.NewCase(row.getRequestId(),"Changed","Description")));}
 @Test void otherCustomersCannotReadWriteOrSeeMessagesAndHistory(){row.setCustomerId(8L);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.detail(false,9L));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.messages(false,9L,0));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.history(false,9L,0));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.send(false,9L,new ClientCaseService.Message(UUID.randomUUID().toString(),"Body")));verifyNoInteractions(messages,events);}
 @Test void ownListIsServerFilteredAndPaged(){when(cases.search(any(),any(),any())).thenReturn(Page.empty());service.list(false,"OPEN",2);verify(cases).search(eq(7L),eq("OPEN"),argThat(p->p.getPageSize()==20&&p.getPageNumber()==2));}
 @Test void sharedMessageUsesAuthenticatedActorAndReducedResponse(){var r=service.send(false,9L,new ClientCaseService.Message(UUID.randomUUID().toString()," Hello "));assertEquals("CLIENT",r.senderKind());assertEquals("Hello",r.body());assertEquals(4,r.getClass().getRecordComponents().length);verify(messages).saveAndFlush(argThat(m->m.getAuthorId().equals(42L)&&m.getCaseId().equals(9L)));}
 @Test void sameMessageUuidIsIdempotentAndDifferentAuthorOrBodyConflicts(){var old=new ClientCaseMessage();old.setId(11L);old.setCaseId(9L);old.setAuthorId(42L);old.setSenderKind("CLIENT");old.setBody("Hello");String key=UUID.randomUUID().toString();when(messages.findByRequestId(key)).thenReturn(Optional.of(old));service.send(false,9L,new ClientCaseService.Message(key,"Hello"));verify(messages,never()).saveAndFlush(any());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.send(false,9L,new ClientCaseService.Message(key,"Other")));}
 @Test void resolvedRequestsAreReadOnlyForMessages(){row.setStatus("RESOLVED");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.send(false,9L,new ClientCaseService.Message(UUID.randomUUID().toString(),"Hello")));verify(messages,never()).saveAndFlush(any());}
 @Test void clientCannotChangeStatusOrUseAdminService(){assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.state(9L,new ClientCaseService.State("RESOLVED")));assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.detail(true,9L));}
 @Test void administratorCanReplyChangeStatusAndReopenWithHistory(){AssignedContactPolicyTest.role("ADMIN");service.send(true,9L,new ClientCaseService.Message(UUID.randomUUID().toString(),"Team"));verify(messages).saveAndFlush(argThat(m->m.getSenderKind().equals("TEAM")));service.state(9L,new ClientCaseService.State("RESOLVED"));service.state(9L,new ClientCaseService.State("OPEN"));assertEquals("OPEN",row.getStatus());verify(events,times(2)).saveAndFlush(any());verifyNoInteractions(personal);}
 @Test void duplicateStatusDoesNotCreateDuplicateEvent(){AssignedContactPolicyTest.role("SUPER_ADMIN");service.state(9L,new ClientCaseService.State("OPEN"));verifyNoInteractions(events);}
 @Test void archivedCustomerCannotCreateNewCaseButHistoryRemainsReadable(){contact.setArchived(true);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.create(new ClientCaseService.NewCase(UUID.randomUUID().toString(),"Subject","Body")));assertEquals("9",service.detail(false,9L).id());}
 @Test void invalidUuidBodyStatusAndPageAreRefused(){assertThrows(IllegalArgumentException.class,()->service.create(new ClientCaseService.NewCase("bad","Subject","Body")));assertThrows(IllegalArgumentException.class,()->service.send(false,9L,new ClientCaseService.Message(UUID.randomUUID().toString()," ")));AssignedContactPolicyTest.role("ADMIN");assertThrows(IllegalArgumentException.class,()->service.state(9L,new ClientCaseService.State("PRIVATE")));assertThrows(IllegalArgumentException.class,()->service.list(true,null,-1));}
}
